#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int nWidth;  COLORREF  lg;// Цвет края  COLORREF  fn;// Цвет центра  COLORREF  dk;// Цвет края  HRGN m_hRgn;  } Queue_PipeV;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция удаленияvoid ClearPipeV(SQueue& q,void* s)  {  Queue_PipeV* p = (Queue_PipeV*)s;  ::DeleteObject( p->m_hRgn );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SetT(RGBTRIPLE& val,COLORREF color);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintPipeV(DefinePaint)  {  QueueP(Queue_PipeV);  if ( q.curShift.x || q.curShift.y )  ::OffsetRgn( p->m_hRgn, -q.curShift.x, -q.curShift.y );  //  if ( p->fn == p->dk )    {    HBRUSH hBrush = ::CreateSolidBrush(p->fn);    if ( hBrush )      {      ::FillRgn( hDC, p->m_hRgn, hBrush );      ::DeleteObject( hBrush );      }    }  else  if ( p->lg == p->dk )    {    RGBTRIPLE rgb[2];//0-центр,1-край    SetT( rgb[0], p->fn );//0-центр    SetT( rgb[1], p->dk );//1-край    int m = p->nWidth/2;    ::SelectClipRgn( hDC, p->m_hRgn );    RECT rect = p->mRect;    ::InflateRect( &rect, 0, m );    for ( int n = 0; n <= m; n++ )      {      COLORREF color = Col(rgb[1],rgb[0],(int)n,m);      CMyBrush brs( hDC, color );      brs.Rect(rect);      ::InflateRect( &rect, -1, 0 );      }    ::SelectClipRgn( hDC, NULL );    }  else    {    }  //  if ( q.curShift.x || q.curShift.y )  ::OffsetRgn( p->m_hRgn,  q.curShift.x,  q.curShift.y );  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPipeV(DefineTegs)  {  AddQueueEx(Queue_PipeV);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPipeV;  p->clear = &ClearPipeV;  //  int nWidth = 5;  EDirect eFrom = dirFree, eTo = dirFree;  {  POINT pt;  int   y1;  //  STegObj obj[] =    {    { 'I', "w"    , &nWidth },    { 'I', "width", &nWidth },    { 'P', "pt"   , &pt     },    { 'I', "x"    , &pt.x   },    { 'I', "x0"   , &pt.x   },    { 'I', "y"    , &pt.y   },    { 'I', "y0"   , &pt.y   },    { 'I', "y1"   , &y1     },    { 'I', "z"    , &y1     },    { 'N', "from" , &eFrom  },    { 'N', "to"   , &eTo    },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->mRect.left   = pt.x-nWidth/2;  p->mRect.right  = p->mRect.left+nWidth;  bool bUp = pt.y > y1;  if ( bUp )    {    p->mRect.top    = y1;    p->mRect.bottom = pt.y;    EDirect eTemp = eTo;    eTo   = eFrom;    eFrom = eTemp;    }  else    {    p->mRect.top    = pt.y;    p->mRect.bottom = y1;    }  }  //  p->nWidth = nWidth;  p->lg = def.lgPipe;// Цвет края  p->fn = def.fnPipe;// Цвет центра  p->dk = def.dkPipe;// Цвет края  //  // Регион вывода трубки  int m = nWidth/2;  POINT pt[6] = {{p->mRect.left,p->mRect.top},{p->mRect.left+m,p->mRect.top},{p->mRect.right,p->mRect.top},                 {p->mRect.right,p->mRect.bottom},{p->mRect.left+m,p->mRect.bottom},{p->mRect.left,p->mRect.bottom}};  //  if ( eFrom != dirFree || eTo != dirFree )    {    if ( eFrom != dirFree )    switch ( eFrom )      {      case dirLeft : pt[0].y += m;pt[2].y = pt[0].y-nWidth;break;      case dirRight: pt[0].y -= m;pt[2].y = pt[0].y+nWidth;break;      case dirInner: pt[0].y += m;pt[2].y += m;break;      }    if ( eTo != dirFree )    switch ( eTo )      {      case dirLeft : pt[5].y -= m;pt[3].y = pt[5].y+nWidth;break;      case dirRight: pt[5].y += m;pt[3].y = pt[5].y-nWidth;break;      case dirInner: pt[5].y -= m;pt[3].y -= m;break;      }    }  //  p->m_hRgn = ::CreatePolygonRgn( pt, 6, WINDING );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~